class Solution {
    public TreeNode upsideDownBinaryTree(TreeNode root) {
        TreeNode curr = root;
        TreeNode prev = null;
        TreeNode prevRight = null;
        while (curr != null) {
            TreeNode nextLeft = curr.left;
            TreeNode nextRight = curr.right;
            curr.left = prevRight;
            curr.right = prev;
            prev = curr;
            prevRight = nextRight;
            curr = nextLeft;
        }
        return prev;
    }
}

/**
 * @param {TreeNode} root
 * @return {TreeNode}
 */
var upsideDownBinaryTree = function(root) {
    let curr = root;
    let prev = null;
    let prevRight = null;
    while (curr !== null) {
        const nextLeft = curr.left;
        const nextRight = curr.right;
        curr.left = prevRight;
        curr.right = prev;
        prev = curr;
        prevRight = nextRight;
        curr = nextLeft;
    }
    return prev;
};
